describe('Product Image and Login Field Accessibility', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display accessible attributes on login fields and product images', () => {
    // Verify login fields have placeholder attributes
    cy.get('[data-test="username"]').should('have.attr', 'placeholder').and('not.be.empty');
    cy.get('[data-test="password"]').should('have.attr', 'placeholder').and('not.be.empty');

    // Verify product images have alt attributes
    cy.get('[data-test="inventory-item-sauce-labs-backpack-img"]').should('have.attr', 'alt').and('not.be.empty');
    cy.get('[data-test="inventory-item-sauce-labs-bike-light-img"]').should('have.attr', 'alt').and('not.be.empty');
    cy.get('[data-test="inventory-item-sauce-labs-bolt-t-shirt-img"]').should('have.attr', 'alt').and('not.be.empty');
    cy.get('[data-testid="inventory-item-sauce-labs-fleece-jacket-img"]').should('have.attr', 'alt').and('not.be.empty');
    cy.get('[data-testid="inventory-item-sauce-labs-onesie-img"]').should('have.attr', 'alt').and('not.be.empty');

    // Verify login fields are visible and interactable
    cy.get('[data-test="username"]').should('be.visible').and('be.attr', 'type', 'text');
    cy.get('[data-test="password"]').should('be.visible').and('be.attr', 'type', 'password');

    // Verify login button is present
    cy.get('[data-test="login-button"]').should('be.visible');

    // Verify product titles are present and accessible
    cy.get('[data-testid="inventory-item-sauce-labs-backpack-title-link"]').should('be.visible').and('contain', 'Sauce Labs Backpack');
    cy.get('[data-testid="inventory-item-sauce-labs-bike-light-title-link"]').should('be.visible').and('contain', 'Sauce Labs Bike Light');
  });

  it('should handle edge case with empty or missing alt attributes', () => {
    // Intercept login to bypass UI interaction and test accessibility attributes directly
    cy.intercept('POST', '/api/login').as('loginRequest');

    // Attempt to log in with invalid credentials to test error state accessibility
    cy.get('[data-test="username"]').type('invaliduser');
    cy.get('[data-test="password"]').type('wrongpassword');
    cy.get('[data-test="login-button"]').click();

    cy.wait('@loginRequest');

    // Verify error message is displayed and accessible
    cy.get('[data-testid="error-message"]').should('be.visible').and('contain', 'Invalid username or password');

    // Verify product images still have alt attributes even in error state
    cy.get('[data-test="inventory-item-sauce-labs-backpack-img"]').should('have.attr', 'alt').and('not.be.empty');
    cy.get('[data-test="inventory-item-sauce-labs-bike-light-img"]').should('have.attr', 'alt').and('not.be.empty');

    // Verify login fields still have placeholder attributes
    cy.get('[data-test="username"]').should('have.attr', 'placeholder').and('not.be.empty');
    cy.get('[data-test="password"]').should('have.attr', 'placeholder').and('not.be.empty');
  });
});
